        <fieldset class="flex flex-wrap items-center gap-4"><legend class="field-label"><?= pl_e(pl_t('Transaction type')) ?></legend><label><input type="radio" name="kind" value="expense" <?= $kind !== 'receipt' ? 'checked' : '' ?>> <?= pl_e(pl_t('Money out · Expense')) ?></label><label><input type="radio" name="kind" value="receipt" <?= $kind === 'receipt' ? 'checked' : '' ?>> <?= pl_e(pl_t('Money in · Receipt')) ?></label></fieldset>
        <div class="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <?php pl_ui_field('transaction-date',pl_t('Date'),static function () use ($input,$document,$form,$errors): void { ?><input class="input" id="transaction-date"<?= pl_ui_error_attributes('transaction-date',$errors['date']??'') ?> type="date" name="date" value="<?= pl_e(pl_web_text($input,'date')) ?>" required <?= !$document && !$form['input'] ? 'data-local-today' : '' ?>><?php }, pl_t('The accounting date for this transaction.'), $errors['date']??''); ?>
        <?php pl_ui_field('transaction-amount',pl_t('Amount ({currency})', ['currency' => $company['currency']]),static function () use ($input,$errors): void { ?><input class="input input-amount" id="transaction-amount"<?= pl_ui_error_attributes('transaction-amount',$errors['amount']??'') ?> type="text" inputmode="decimal" name="amount" value="<?= pl_e(pl_web_text($input,'amount')) ?>" placeholder="0.00" maxlength="21" pattern="[0-9]+(\.[0-9]{1,4})?" required autocomplete="off"><?php }, pl_t('Use a decimal point, without separators.'), $errors['amount']??''); ?>
        <?php pl_ui_field('transaction-party',pl_t('Counterparty name'),static function () use ($input,$errors): void { ?><input class="input" id="transaction-party"<?= pl_ui_error_attributes('transaction-party',$errors['counterparty']??'') ?> name="counterparty" value="<?= pl_e(pl_web_text($input,'counterparty')) ?>" maxlength="160" required><?php }, '', $errors['counterparty']??''); ?>
        <?php pl_ui_field('transaction-cash',pl_t('Cash / bank account'),static function () use ($cashAccounts,$cashId,$errors): void { ?><select class="select" id="transaction-cash"<?= pl_ui_error_attributes('transaction-cash',$errors['money_account_id']??'') ?> name="money_account_id" required><option value=""><?= pl_e(pl_t('Choose a cash / bank account')) ?></option><?php if ($cashId && !in_array($cashId,array_map(static fn(array $a):int=>(int)$a['id'],$cashAccounts),true)): ?><option value="<?= $cashId ?>" selected><?= pl_e(pl_t('Unavailable saved account — choose another')) ?></option><?php endif; ?><?php foreach ($cashAccounts as $account): ?><option value="<?= (int)$account['id'] ?>" <?= $cashId === (int)$account['id'] ? 'selected' : '' ?>><?= pl_e($account['name']) ?></option><?php endforeach; ?></select><?php }, '', $errors['money_account_id']??''); ?>
        <?php pl_ui_field('transaction-category',pl_t('Category'),static function () use ($categoryAccounts,$input,$errors): void { ?><select class="select" id="transaction-category"<?= pl_ui_error_attributes('transaction-category',$errors['category_account_id']??'') ?> name="category_account_id" required><option value=""><?= pl_e(pl_t('Choose a category')) ?></option><?php $categoryId=pl_web_id($input,'category_account_id'); if ($categoryId && !in_array($categoryId,array_map(static fn(array $a):int=>(int)$a['id'],$categoryAccounts),true)): ?><option value="<?= $categoryId ?>" selected><?= pl_e(pl_t('Unavailable saved category — choose another')) ?></option><?php endif; ?><?php foreach ($categoryAccounts as $account): ?><option value="<?= (int)$account['id'] ?>" data-category-kind="<?= $account['type'] === 'income' ? 'receipt' : 'expense' ?>" <?= pl_web_id($input,'category_account_id') === (int)$account['id'] ? 'selected' : '' ?>><?= pl_e($account['name']) ?></option><?php endforeach; ?></select><?php }, '', $errors['category_account_id']??''); ?>
