        <section class="rounded-panel border border-border p-3" aria-labelledby="posting-preview-title">
            <div class="flex flex-wrap items-center justify-between gap-2"><h2 class="section-title" id="posting-preview-title"><?= pl_e(pl_t('Posting preview')) ?></h2><button class="btn btn-secondary btn-sm" name="editor_action" value="preview" type="submit"><?= pl_e(pl_t('Update posting preview')) ?></button></div>
            <?php if ($preview): ?><div class="mt-3" data-server-preview><?php $entryLines=$preview['lines']; require __DIR__ . '/../partials/entry.php'; ?></div><p class="text-xs text-ink-muted mt-2"><?= pl_e(pl_t('This preview uses the same posting payload as the saved transaction. Update it after changing fields. Permissions, revisions and open periods are checked again when posting.')) ?></p><?php else: ?><p class="text-xs text-ink-muted mt-2"><?= pl_e(pl_t('Enter the transaction details, then update the preview to inspect the exact journal lines without saving or posting.')) ?></p><?php endif; ?>
            <p class="text-xs text-ink-muted mt-2"><?= pl_e(pl_t('Posting adds this transaction to reports. A saved draft does not change your books.')) ?></p>
